/**
 * @param {number[]} A
 * @param {number[]} B
 * @return {number[]}
 */
var findThePrefixCommonArray = function(A, B) {
    const n = A.length;
    const freq = Array(n + 1).fill(0);
    const res = Array(n);
    let count = 0;

    for (let i = 0; i < n; i++) {
        freq[A[i]]++;
        if (freq[A[i]] <= 0) count++;

        freq[B[i]]--;
        if (freq[B[i]] >= 0) count++;

        res[i] = count;
    }

    return res;
};
